 #[test]fn native_under_attack_notice_projection_matches_64_actual_callers(){
  let mut hash=2166136261u32;
  for scenario in 0..64u32{
   let hardware=scenario&1!=0;let camera=(scenario/2&1)as i16*1000;let local=(scenario/4&1)as u8;let enabled=scenario/8&1!=0;let cooldown=if scenario/16&1!=0{5}else{0};let busy=scenario/32&1!=0;
   let mut g=field();g.multiplayer=true;g.native_feedback.ui_clock=500;g.native_view=Some(([camera,0],[640,480]));g.native_display.fort_visible=[2,2,0,0];
   for(i,team,group,x)in[(0,1,4,200.),(1,0,3,2400.)]{let slot=g.units[i].native_slot.unwrap();g.units[i].team=team;g.units[i].x=x;g.units[i].y=200.;let m=g.native_group_rosters.members[slot].as_mut().unwrap();m.flags31=(team as u8)|4;m.flags69=0;m.group=group;}
   g.native_group_rosters.pool[3].roster[64]=if hardware{0}else{cooldown};g.native_group_rosters.pool[4].roster[64]=if hardware{cooldown}else{0};g.events.clear();
   let rng=g.original_rng.words;let crt=g.native_cosmetic_rng;let mut projection=None;
   g.for_native_listeners(|g|{if g.native_feedback.local_team!=local{return;}
    let f=&mut g.native_feedback;f.scene_gate=0;f.portraits_enabled=1;f.portrait_mode=if busy{4}else{2};f.current_message=if busy{0x419}else{0};f.interruptible=0;f.speaker=None;f.display_speaker=None;f.sound_enabled=u8::from(enabled);f.ui_clock=500;f.attack_membership.fill(0);
    g.native_audio.notice_counter=3;for bank in &mut g.native_audio.last{bank.fill(0);}
    g.native_attack_feedback(0,1,hardware);
    let played=g.events.iter().any(|e|e["kind"]=="nativeVoice"&&e["playAudio"]==true);let speaker=g.native_feedback.speaker.map_or(-1,|s|s as i32);
    projection=Some([scenario,u32::from(played),u32::from(g.native_group_rosters.pool[3].roster[64]),u32::from(g.native_group_rosters.pool[4].roster[64]),speaker as u32,u32::from(g.native_feedback.portrait_mode),g.native_feedback.current_message as u32,g.native_audio.notice_counter as u16 as u32]);
   });
   assert_eq!(g.original_rng.words,rng);assert_eq!(g.native_cosmetic_rng,crt);
   let allowed=camera==0&&local==u8::from(hardware)&&cooldown==0;let played=allowed&&!busy&&enabled;
   let expected=[scenario,u32::from(played),u32::from(if allowed&&!hardware{68}else if !hardware{cooldown}else{0}),u32::from(if allowed&&hardware{68}else if hardware{cooldown}else{0}),if allowed{u32::from(!hardware)}else{u32::MAX},if allowed||busy{4}else{2},if allowed||busy{0x419}else{0},if played{0}else{3}];
   let actual=projection.unwrap();assert_eq!(actual,expected,"actual native feedback projection row{scenario}");for n in actual{hash=(hash^n).wrapping_mul(16777619);}
  }
  assert_eq!(hash,2074623945,"64 original caller projections: play/cooldown/speaker/portrait/notice lowword");
 }

